const data = $input.first().json;

const candidateId   = data.candidateId;
const firstName     = data.firstName || 'Candidat';
const lastName      = data.lastName  || '';
const jobTitle      = data.jobOfferTitle || 'le poste';
const status        = data.status || 'CV_REVIEWED';
const cvUrl         = data.cvUrl  || null;
const email         = data.email  || '';
const hrName        = data.updatedBy || 'RH';
const managerEmail  = data.managerEmail || null;

// Mapping statut → label lisible
const statusLabels = {
  CV_REVIEWED:       '✅ CV validé — en attente d\'analyse Manager',
  PHONE_SCREENING:   '📞 Pré-qualification téléphonique',
  TECHNICAL_TEST:    '💻 Test technique à planifier',
  INTERVIEW:         '🎤 Entretien à planifier',
  FINAL_INTERVIEW:   '🏆 Entretien final',
  ACCEPTED:          '🎉 Candidat accepté',
  REJECTED:          '❌ Candidat refusé'
};
const statusLabel = statusLabels[status] || status;
const profileUrl = `http://localhost:4200/admin/candidates`;

return [{ json: {
  candidateId, firstName, lastName, email, jobTitle,
  status, statusLabel, cvUrl, hrName, managerEmail, profileUrl,
  validatedAt: new Date().toISOString()
} }];
